#!/usr/bin/env python3
"""robots.txt is generated by build/build.py (ROBOTS), not read from site/.

site/ is rebuilt by CI before every deploy, so a hand edit to site/robots.txt is
overwritten. This pins the weekly sitemap line in the generator.

    python3 -m unittest discover -s tests
"""

import pathlib
import re
import sys
import unittest

ROOT = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "build"))

import build  # noqa: E402

HOST = "https://miamicontactimprov.com"


class RobotsSitemaps(unittest.TestCase):
    def sitemaps(self):
        return re.findall(r"^Sitemap: (\S+)$", build.ROBOTS, re.M)

    def test_main_sitemap(self):
        self.assertIn(f"{HOST}/sitemap.xml", self.sitemaps())

    def test_weekly_sitemap(self):
        self.assertIn(f"{HOST}/blog/weekly/sitemap.xml", self.sitemaps())


if __name__ == "__main__":
    unittest.main()
